begin;
-- KOWI School AI is additive. public.projects is the shared KOWI Projects table.
create table public.school_profiles(id uuid primary key default gen_random_uuid(),user_id uuid not null unique default auth.uid() references auth.users(id) on delete cascade,goal text not null default '',locale text not null default 'es' check(locale in('es','en')),plan text not null default 'free' check(plan in('free','professional','business')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.skill_definitions(id text primary key,title text not null,description text not null default '',domain text not null default 'general',sort_order int not null default 0);
create table public.student_skills(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,skill_id text not null references public.skill_definitions(id) on delete cascade,level text not null check(level in('NOT STARTED','FOUNDATIONAL','OPERATIONAL','COMPETENT','ADVANCED','VERIFIED')),verified_at timestamptz,last_practiced_at timestamptz,evidence_count int not null default 0 check(evidence_count>=0),unique(user_id,skill_id));
create table public.learning_paths(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,goal text not null,level_ids int[] not null default '{}',status text not null default 'active' check(status in('active','completed','paused')),created_at timestamptz not null default now());
create table public.courses(id int primary key,title text not null,slug text not null unique,outcome text not null,published boolean not null default true,plan text not null default 'free' check(plan in('free','professional','business')));
create table public.modules(id uuid primary key default gen_random_uuid(),course_id int not null references public.courses(id) on delete cascade,title text not null,sort_order int not null default 0);
create table public.lessons(id uuid primary key default gen_random_uuid(),module_id uuid not null references public.modules(id) on delete cascade,title text not null,content jsonb not null default '{}'::jsonb,sort_order int not null default 0,published boolean not null default true);
create table public.resources(id uuid primary key default gen_random_uuid(),lesson_id uuid references public.lessons(id) on delete cascade,source text not null,author text,url text not null,language text not null default 'es',level text not null default 'foundational',license_status text not null default 'link_only',last_checked_at timestamptz,available boolean not null default true);
create table public.exercises(id uuid primary key default gen_random_uuid(),lesson_id uuid not null references public.lessons(id) on delete cascade,title text not null,instructions text not null,rubric jsonb not null default '{}'::jsonb);
create table public.assessments(id uuid primary key default gen_random_uuid(),course_id int not null references public.courses(id) on delete cascade,title text not null,rubric jsonb not null default '{}'::jsonb,practical boolean not null default true);
create table public.assessment_attempts(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,assessment_id uuid not null references public.assessments(id) on delete cascade,submission jsonb not null default '{}'::jsonb,score numeric check(score between 0 and 100),status text not null default 'submitted' check(status in('draft','submitted','reviewed')),created_at timestamptz not null default now());
create table public.evidence(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,skill_id text references public.skill_definitions(id),course_id int references public.courses(id),kind text not null default 'artifact',description text not null,artifact_url text,verification_status text not null default 'PENDING' check(verification_status in('PENDING','VERIFIED','REJECTED')),verified_at timestamptz,created_at timestamptz not null default now());
create table public.credentials(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,title text not null,issuer text not null default 'KOWI',credential_type text not null default 'internal',evidence_id uuid references public.evidence(id),issued_at timestamptz,revoked_at timestamptz,external_url text);
create table public.portfolios(id uuid primary key default gen_random_uuid(),user_id uuid not null unique default auth.uid() references auth.users(id) on delete cascade,headline text not null default '',summary text not null default '',is_public boolean not null default false,updated_at timestamptz not null default now());
create table public.learning_events(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,event_type text not null,course_id int references public.courses(id),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table public.school_agents(agent_id text primary key,role text not null,permissions text[] not null default '{}',tools text[] not null default '{}',risk_level text not null check(risk_level in('low','medium','high')),budget jsonb not null default '{"max_calls_per_session":20}'::jsonb,status text not null check(status in('DRAFT','ACTIVE','PAUSED','REVOKED','TERMINATED')));
create table public.school_project_links(id uuid primary key default gen_random_uuid(),user_id uuid not null default auth.uid() references auth.users(id) on delete cascade,project_id uuid not null references public.projects(id) on delete cascade,course_id int references public.courses(id),created_at timestamptz not null default now(),unique(user_id,project_id));

select m.id,'Study → Build → Test → Execute → Prove',jsonb_build_object('discover','Define el problema','learn','Aprende el concepto mínimo','try','Haz una prueba guiada','build','Construye un entregable','break','Introduce un fallo','fix','Diagnostica y corrige','execute','Obtén un resultado reproducible','explain','Explica decisiones','prove','Resuelve sin guía','evidence','Guarda evidencia verificable'),1 from public.modules m where not exists(select 1 from public.lessons l where l.module_id=m.id);


alter table public.school_profiles enable row level security;alter table public.skill_definitions enable row level security;alter table public.student_skills enable row level security;alter table public.learning_paths enable row level security;alter table public.courses enable row level security;alter table public.modules enable row level security;alter table public.lessons enable row level security;alter table public.resources enable row level security;alter table public.exercises enable row level security;alter table public.assessments enable row level security;alter table public.assessment_attempts enable row level security;alter table public.evidence enable row level security;alter table public.credentials enable row level security;alter table public.portfolios enable row level security;alter table public.learning_events enable row level security;alter table public.school_agents enable row level security;alter table public.school_project_links enable row level security;
revoke all on public.school_profiles,public.skill_definitions,public.student_skills,public.learning_paths,public.courses,public.modules,public.lessons,public.resources,public.exercises,public.assessments,public.assessment_attempts,public.evidence,public.credentials,public.portfolios,public.learning_events,public.school_agents,public.school_project_links from anon,authenticated;
grant select on public.skill_definitions,public.courses,public.modules,public.lessons,public.resources,public.exercises,public.assessments to anon,authenticated;
grant select,insert,update,delete on public.school_profiles,public.student_skills,public.learning_paths,public.assessment_attempts,public.evidence,public.portfolios,public.learning_events,public.school_project_links to authenticated;
grant select on public.credentials to authenticated;
create policy school_public_skills on public.skill_definitions for select to anon,authenticated using(true);create policy school_public_courses on public.courses for select to anon,authenticated using(published);create policy school_public_modules on public.modules for select to anon,authenticated using(true);create policy school_public_lessons on public.lessons for select to anon,authenticated using(published);create policy school_public_resources on public.resources for select to anon,authenticated using(available);create policy school_public_exercises on public.exercises for select to anon,authenticated using(true);create policy school_public_assessments on public.assessments for select to anon,authenticated using(true);
do $$ declare t text; begin foreach t in array array['school_profiles','student_skills','learning_paths','assessment_attempts','evidence','portfolios','learning_events','school_project_links'] loop execute format('create policy %I on public.%I for select to authenticated using ((select auth.uid())=user_id)',t||'_select',t);execute format('create policy %I on public.%I for insert to authenticated with check ((select auth.uid())=user_id)',t||'_insert',t);execute format('create policy %I on public.%I for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id)',t||'_update',t);execute format('create policy %I on public.%I for delete to authenticated using ((select auth.uid())=user_id)',t||'_delete',t);end loop;end $$;
create policy school_credentials_select on public.credentials for select to authenticated using((select auth.uid())=user_id);
create index student_skills_owner on public.student_skills(user_id,skill_id);create index learning_paths_owner on public.learning_paths(user_id,created_at desc);create index attempts_owner on public.assessment_attempts(user_id,created_at desc);create index evidence_owner on public.evidence(user_id,created_at desc);create index learning_events_owner on public.learning_events(user_id,created_at desc);
commit;